function pyjson(s,claimedRule){
  let o='"';
  for(const ch of s){ const c=ch.codePointAt(0);
    if(ch==='"')o+='\\"';
    else if(ch==='\\')o+='\\\\';
    else if(c===0x09)o+='\\t';
